def load() -> pd.DataFrame:
    import openpyxl
    wb = openpyxl.load_workbook('data/biomedical/input/1-s2.0-S0092867420301070-mmc4.xlsx')
    sheet_names = wb.sheetnames
    result_data = []
    for sheet_name in sheet_names:
        result_data.append({'sheet_name': sheet_name})
    return pd.DataFrame(result_data)

def process(find_target_peptide_alt_splice) -> pd.DataFrame:
    if len(find_target_peptide_alt_splice) == 0:
        return pd.DataFrame(columns=['sample_id'])
    samples_str = find_target_peptide_alt_splice.iloc[0]['Samples_With_Peptide']
    sample_list = [s.strip() for s in str(samples_str).split(',')]
    return pd.DataFrame({'sample_id': sample_list})

def process(extract_sample_ids, get_clinical_data) -> pd.DataFrame:
    merged = extract_sample_ids.merge(get_clinical_data, left_on='sample_id', right_on='idx', how='inner')
    return merged[['sample_id', 'Histologic_Grade_FIGO']]

def process(join_samples_with_grades) -> pd.DataFrame:
    grades = join_samples_with_grades['Histologic_Grade_FIGO'].dropna().unique().tolist()
    return pd.DataFrame({'grades': [grades]})
